                if x not in assigned and ld + demands[x] <= capacity:
                    nr.append(x)
                    assigned.add(x)
                    ld += demands[x]
            if nr:
                repaired.append(nr)
        for c in customers:
            if c not in assigned:
                placed = False
                for r in range(len(repaired)):
                    ld = 0
                    for x in repaired[r]:
                        ld += demands[x]
                    if ld + demands[c] <= capacity:
                        pos, _ = best_insertion(repaired[r], c)
                        repaired[r].insert(pos, c)
                        assigned.add(c)
                        placed = True
                        break
                if not placed:
                    repaired.append([c])
        final_routes = repaired

    return final_routes
